# generated by darshan-singh-meel-docs-v2
"""Which spec sections a docs update must edit. From the repo root:
  python -I changed.py --save [docs]   before rerunning inventory.py: _spec/inventory.json -> _spec/inventory.prev.json
  python -I changed.py [docs]          after: prints, per _spec/<doc>.json, the sections to edit and why
  python -I changed.py --done [docs]   after a good build: removes inventory.prev.json
docs = the generated-docs folder (default generated-docs). Inputs: inventory.prev.json vs inventory.json, plus the
graph (knowledge-graph update.py): changed line ranges from git diff since the docs' graph commit (docs_pending.since in
meta.json), else from _update/worklist.json; deleted and renamed files and removed nodes from the worklist."""
import json, re, shutil, subprocess, sys
from pathlib import Path

NUM = re.compile(r"(?<=:)\d+(-\d+)?")
CITE = re.compile(r"([\w./-]+\.\w+):(\d+)(?:-(\d+))?")
NOT_SPEC = {"inventory.json", "inventory.prev.json", "facts.json"}


def records(inv):
    """inventory -> {key: record} for every item the docs may show."""
    out = {}
    for t, rows in inv.get("items", {}).items():
        out |= {f"{t}:{r.get('path')}:{r.get('name')}": r for r in rows}
    for k in ("flows", "entry_points", "data_objects"):
        out |= {f"{r.get('type') or r.get('group') or k}:{r.get('path')}:{r.get('name')}": r for r in inv.get(k, [])}
    out |= {f"fk:{r.get('from')}->{r.get('to')}": r for r in inv.get("fks", [])}
    out |= {f"test:{r}": {"name": r, "path": r} for r in inv.get("tests", [])}
    return out


def find_graph(root):
    p = root / ".knowledge-graph"
    g = (root / p.read_text().strip()) if p.is_file() else root / f"{root.name}-knowledge-graph"
    rd = lambda f: json.loads((g / f).read_text(encoding="utf-8")) if (g / f).is_file() else {}
    return rd("_update/worklist.json"), rd("meta.json")


def diff_ranges(root, since):
    """path -> changed line ranges (old and new positions) from git diff <since> to the working tree; deleted and
    renamed files get the range 0-0 (rename or delete lines carry no hunk)."""
    r = subprocess.run(["git", "-c", "core.quotepath=off", "diff", "-U0", "--no-color", "-M", since], cwd=root,
                       capture_output=True, text=True, encoding="utf-8", errors="replace") if since else None
    if not r or r.returncode:
        return None
    out, a, b = {}, None, None
    for l in r.stdout.splitlines():
        if l.startswith(("rename from ", "deleted file mode")):
            a = l[12:] if l.startswith("rename from ") else a
            out.setdefault(a, []).append((0, 0))
        elif l.startswith("diff --git "):
            a = l.split(" a/", 1)[-1].split(" b/", 1)[0]
        elif l.startswith("--- "):
            a = l[6:] if l.startswith("--- a/") else None
        elif l.startswith("+++ "):
            b = l[6:] if l.startswith("+++ b/") else None
        elif l.startswith("@@"):
            m = re.match(r"@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@", l)
            for p, x, n in ((a, m[1], m[2]), (b, m[3], m[4])):
                if p and n != "0":
                    x = int(x)
                    out.setdefault(p, []).append((max(x, 1), x + max(int(n or 1), 1) - 1))
    return out


def main(argv):
    sys.stdout.reconfigure(encoding="utf-8")
    args = [a for a in argv if not a.startswith("--")]
    docs, root = Path(args[0] if args else "generated-docs"), Path(".").resolve()
    spec = docs / "_spec"
    prev = spec / "inventory.prev.json"
    if "--done" in argv:
        prev.unlink(missing_ok=True)
        return print("removed _spec/inventory.prev.json")
    if "--save" in argv:
        if prev.is_file():  # a second save would overwrite the old inventory and empty the diff
            sys.exit("_spec/inventory.prev.json exists (refresh not finished): run changed.py; after a good build changed.py --done")
        shutil.copy(spec / "inventory.json", prev)
        return print("saved _spec/inventory.prev.json; now rerun inventory.py, then changed.py")
    new = records(json.loads((spec / "inventory.json").read_text(encoding="utf-8")))
    # no previous inventory: item changes unknown, so no item diff (not "everything is new")
    old = records(json.loads(prev.read_text(encoding="utf-8"))) if prev.is_file() else new
    diff = {k: "new" for k in new.keys() - old.keys()} | {k: "removed" for k in old.keys() - new.keys()}
    # fields a newer templates version added are not changes in the code
    norm = lambda r, o: NUM.sub("", json.dumps({k: v for k, v in r.items() if k != "line" and k in o}, sort_keys=True))
    both = [k for k in new.keys() & old.keys() if new[k] != old[k]]
    diff |= {k: "changed" for k in both if norm(new[k], old[k]) != norm(old[k], new[k])}
    # moved = only line numbers differ: a section needs edits only where it cites the old line
    cites = lambda r: {m[0] for m in CITE.finditer(json.dumps(r))} | {f"{r.get('path')}:{r.get('line')}"}
    moved = {c for k in both if k not in diff for c in cites(old[k]) - cites(new[k])}
    work, meta = find_graph(root)
    f = work.get("files", {})
    gone = set(f.get("deleted", [])) | set(f.get("renamed", {}))
    ranges = diff_ranges(root, (meta.get("docs_pending") or {}).get("since") or work.get("base"))
    gone |= {p for p, rs in (ranges or {}).items() if (0, 0) in rs}
    if ranges is None:  # no git: the latest worklist's changed nodes (new and old positions)
        ranges = {}
        for r in work.get("refresh", []):
            if r.get("why") != "neighbour":
                for at in (r.get("at"), r.get("was")):
                    m = CITE.fullmatch(at or "")
                    if m:
                        ranges.setdefault(m[1], []).append((int(m[2]), int(m[3] or m[2])))
    names = {k: (old.get(k) or new.get(k)).get("name") for k in diff}
    names = {k: n for k, n in names.items() if isinstance(n, str) and len(n) > 3}
    names |= {i: i.rsplit(":", 1)[-1] for i in work.get("removed", []) if len(i.rsplit(":", 1)[-1]) > 3}
    if not prev.is_file():
        print("no inventory.prev.json: item changes unknown, only cited lines and files checked (run --save before inventory.py next time)")
    placed = set()
    for sp in sorted(p for p in spec.glob("*.json") if p.name not in NOT_SPEC):
        s = json.loads(sp.read_text(encoding="utf-8"))
        parts = {f"tab {k}": v for k, v in s.get("tabs", {}).items()} | s.get("sections", {})
        hits = []
        for name, body in parts.items():
            text, why = json.dumps(body, ensure_ascii=False), []
            why += [f"{diff.get(k, 'removed')} {k}" for k, n in names.items()
                    if re.search(rf"(?<![\w/]){re.escape(n)}(?![\w/])", text) and placed.add(k) is None]
            why += [f"line moved {c}" for c in sorted(moved) if re.search(rf"{re.escape(c)}(?![\d-])", text)]
            why += [f"cites deleted/renamed {p}" for p in sorted(gone) if p in text]
            for m in CITE.finditer(text):
                a, b = int(m[2]), int(m[3] or m[2])
                if any(a <= y and x <= b for x, y in ranges.get(m[1], [])):
                    why.append(f"cites changed code {m[0]}")
            if why:
                hits.append(f"  {name}: " + "; ".join(dict.fromkeys(why)))
        print(f"{sp.name}: {len(hits)} sections to edit" + ("".join("\n" + h for h in hits) if hits else ""))
    todo = sorted(k for k, v in diff.items() if v == "new" and k not in placed)
    if todo:
        print("new items in no section yet (add each to its group):\n" + "\n".join(
            f"  {k} ({new[k].get('path')}:{new[k].get('line')})" for k in todo))


if __name__ == "__main__":
    main(sys.argv[1:])
